const { KMSClient, GenerateDataKeyCommand, DecryptCommand } = require('@aws-sdk/client-kms');
const crypto = require('crypto');

const kms = new KMSClient({ region: 'us-east-1' });
const MASTER_KEY_ID = 'arn:aws:kms:us-east-1:123456789012:key/example-key-id';

async function encryptField(plaintextValue) {
  // Ask KMS for a fresh data key. It hands back the plaintext key,
  // used once right here in memory, and the same key already wrapped
  // by the master key that lives inside KMS.
  const { Plaintext, CiphertextBlob } = await kms.send(new GenerateDataKeyCommand({
    KeyId: MASTER_KEY_ID,
    KeySpec: 'AES_256'
  }));

  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', Plaintext, iv);
  const ciphertext = Buffer.concat([cipher.update(plaintextValue, 'utf8'), cipher.final()]);
  const authTag = cipher.getAuthTag();

  // The plaintext data key is never written anywhere. Only its
  // KMS wrapped form gets stored, right next to the ciphertext.
  return {
    ciphertext: ciphertext.toString('base64'),
    iv: iv.toString('base64'),
    authTag: authTag.toString('base64'),
    wrappedDataKey: CiphertextBlob.toString('base64')
  };
}

async function decryptField(record) {
  const { Plaintext } = await kms.send(new DecryptCommand({
    CiphertextBlob: Buffer.from(record.wrappedDataKey, 'base64')
  }));

  const decipher = crypto.createDecipheriv('aes-256-gcm', Plaintext, Buffer.from(record.iv, 'base64'));
  decipher.setAuthTag(Buffer.from(record.authTag, 'base64'));
  const plaintext = Buffer.concat([
    decipher.update(Buffer.from(record.ciphertext, 'base64')),
    decipher.final()
  ]);
  return plaintext.toString('utf8');
}

